#include <wx/sizer.h>

#include "lambda_indent_test_base.h"

bool LambdaIndentTestBase::Create(wxWindow* parent, wxWindowID id, const wxString& title,
    const wxPoint& pos, const wxSize& size, long style, const wxString &name)
{

    if (!wxFrame::Create(parent, id, title, pos, size, style, name))
    {
        return false;
    }
    if (pos != wxDefaultPosition || size != wxDefaultSize)
    {
        SetSize(FromDIP(pos).x, FromDIP(pos).y,
        FromDIP(size).x, FromDIP(size).y, wxSIZE_USE_EXISTING);
    }

    auto* frame_sizer = new wxBoxSizer(wxVERTICAL);

    m_button = new wxButton(this, wxID_ANY, "Click me");
    frame_sizer->Add(m_button, wxSizerFlags().Border(wxALL));
    SetSizerAndFit(frame_sizer);

    Centre(wxBOTH);

    // Event handlers
    m_button->Bind(wxEVT_BUTTON,
        [this](wxCommandEvent&)
        {
            auto name = m_button->GetLabel();
            if (name.size())
                name += ", ";
            m_button->SetLabel(name);
        });

    return true;
}

